    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DecodeResult {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .success(try FfiConverterTypeDecodedData.read(from: &buf)
        )
        
        case 2: return .buffering
        
        case 3: return .unhandled(reason: try FfiConverterTypeUnhandledReason.read(from: &buf), frameData: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DecodeResult, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .success(v1):
            writeInt(&buf, Int32(1))
            FfiConverterTypeDecodedData.write(v1, into: &buf)
            
        
        case .buffering:
            writeInt(&buf, Int32(2))
        
        
        case let .unhandled(reason,frameData):
            writeInt(&buf, Int32(3))
            FfiConverterTypeUnhandledReason.write(reason, into: &buf)
            FfiConverterData.write(frameData, into: &buf)
            
        }
    }
}


